package com.dreamspex.admin;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="services")
public class ServiceOffering { @Id private String id=UUID.randomUUID().toString(); @Column(nullable=false) private String name; @Column(nullable=false,length=2000) private String description; @Column(nullable=false) private String status="ACTIVE"; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); public String getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public int getSortOrder(){return sortOrder;} public void setSortOrder(int v){sortOrder=v;} }
